-- Anonymous product analytics (src/lib/telemetry.ts). Insert-only for clients; read by the admin
-- dashboard with the service role. No ZIP codes, receipt contents or device identifiers.

create table public.app_events (
  id bigint generated always as identity primary key,
  received_at timestamptz not null default now(),
  occurred_at timestamptz not null,
  -- Random per-install UUID generated by the app; not a device or advertising identifier.
  install_id uuid not null,
  session_id uuid not null,
  name text not null check (name in (
    'app_open', 'screen_view', 'onboarding_complete', 'window_change', 'scrub', 'basket_add',
    'basket_remove', 'basket_reorder', 'item_view', 'search', 'barcode_scan', 'receipt_logged',
    'share', 'paywall_view', 'purchase', 'restore', 'alert_toggle', 'alert_delivered', 'error'
  )),
  props jsonb not null default '{}'::jsonb
    check (jsonb_typeof(props) = 'object' and pg_column_size(props) <= 1024),
  platform text not null check (platform in ('ios', 'android', 'web')),
  app_version text not null check (char_length(app_version) <= 32),
  -- Reject clock skew beyond a day either way.
  check (occurred_at between received_at - interval '1 day' and received_at + interval '1 day')
);

create index app_events_received_at_idx on public.app_events (received_at desc);
create index app_events_name_received_at_idx on public.app_events (name, received_at desc);

alter table public.app_events enable row level security;

create policy "Clients may record events" on public.app_events
  for insert to anon, authenticated with check (true);

-- Insert only: no select, update or delete for clients.
revoke all on public.app_events from anon, authenticated;
grant insert (occurred_at, install_id, session_id, name, props, platform, app_version)
  on public.app_events to anon, authenticated;
